import {TOOL_DEFINITIONS, gpa, fitScore, habitStreak, readiness, shiftDay, INTERVIEW_QUESTIONS} from './workspace-tools-model.js';
import {uid,today,escapeHTML as h,dateLabel,download,safeUrl} from './core.js';
export function createWorkspaceTools(ctx) {
 const {getState,mutate,header,btn,ibtn,field,select,textarea,appSelect,formDialog,dialog,toast,csv}=ctx;
 const list=k=>(getState()[k]||[]).filter(x=>!x.archived);
 let timer=null;
 try{timer=JSON.parse(localStorage.getItem('ascend.focus.timer')||'null');}catch{}
 const putTimer=()=>{try{timer?localStorage.setItem('ascend.focus.timer',JSON.stringify(timer)):localStorage.removeItem('ascend.focus.timer');}catch{toast('The focus timer could not be saved.');}};
 const remaining=()=>timer?(timer.end?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.remaining):0;
 const clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
 const metrics=items=>`<div class="tool-metrics">${items.map(([v,l])=>`<div><strong>${h(v)}</strong><span>${h(l)}</span></div>`).join('')}</div>`;
 const weights=()=>getState().profile.decisionWeights||{academics:1,affordability:1,campus:1,opportunity:1};
 function overview(){const day=today(),start=shiftDay(day,-6),minutes=list('focusSessions').filter(r=>r.date>=start&&r.date<=day).reduce((a,r)=>a+Number(r.minutes||0),0);return header('Your studio','More room for school, applications, and everyday progress.')+metrics([[gpa(list('courses'))?.toFixed(2)||'—','Self-reported GPA'],[minutes,'Focus minutes · 7 days'],[`${list('habits').filter(r=>(r.doneDates||[]).includes(day)).length}/${list('habits').length}`,'Habits checked today'],[list('assignments').filter(r=>r.status!=='Done').length,'Open assignments']])+`<div class="studio-shortcuts"><a href="#focus" class="panel"><h2>Focus timer</h2><p>Start a distraction-free work block.</p></a><a href="#readiness" class="panel"><h2>Submission review</h2><p>See required items, deadlines, and receipts.</p></a><a href="#sync" class="panel"><h2>Device sync</h2><p>Your website and iPhone, connected privately.</p></a></div><div class="studio-tool-grid">${TOOL_DEFINITIONS.map(d=>`<a class="panel studio-tool-link" href="#${d.key}"><span class="eyebrow">${list(d.key).length} records</span><h2>${h(d.title)}</h2><p>${h(d.description)}</p><span>Open tool →</span></a>`).join('')}</div>`;}
 function editor(key,id=''){const d=TOOL_DEFINITIONS.find(x=>x.key===key);if(!d)return;const old=(getState()[key]||[]).find(x=>x.id===id),r=old||{title:'',...(key==='interviewPractice'?{question:INTERVIEW_QUESTIONS[Math.floor(Math.random()*INTERVIEW_QUESTIONS.length)]}:{})};const fields=d.fields.map(f=>f.kind==='paragraph'?textarea(f.label,f.key,r[f.key]||'','maxlength="30000"'):f.kind==='choices'?select(f.label,f.key,['',...f.values],r[f.key]||''):field(f.label,f.key,r[f.key]??'',f.kind==='number'?'number':f.kind==='date'?'date':'text',f.kind==='number'?`min="${f.min}" max="${f.max}" step="any"`:'maxlength="2000"')).join('');formDialog(`${old?'Edit':'Add'} ${d.title}`,field('Title','title',r.title,'text','required maxlength="180"')+appSelect(r.applicationId||'')+fields,v=>mutate(()=>{const n={...r,...v,id:old?.id||uid(),updated:Date.now()};for(const f of d.fields)if(f.kind==='number'&&n[f.key]!=='')n[f.key]=Number(n[f.key]);if(key==='habits')n.doneDates=n.doneDates||[];getState()[key]=getState()[key]||[];const i=getState()[key].findIndex(x=>x.id===n.id);i<0?getState()[key].push(n):getState()[key][i]=n;},'Saved'));}
 function toolsPage(key){const d=TOOL_DEFINITIONS.find(x=>x.key===key);if(!d)return null;const rows=list(key);let summary='';if(key==='courses')summary=metrics([[gpa(rows)?.toFixed(2)||'—','Credit-weighted GPA · 0–4'],[rows.length,'Courses']])+`<p class="body-copy">Calculated only from entered credits and 0–4 grade points. No weighting or official transcript conversion is inferred.</p>`;
 if(key==='collegeScores')summary=metrics(Object.entries(weights()).map(([k,v])=>[v,`${k} weight`]))+btn('Adjust decision weights','studio-weights','secondary');
 if(key==='interviewPractice')summary=btn('Practice a new question','studio-add:interviewPractice','secondary');
 const sorted=key==='collegeScores'?[...rows].sort((a,b)=>(fitScore(b,weights())??-1)-(fitScore(a,weights())??-1)):rows;
 return header(d.title,d.description,btn('Add record',`studio-add:${key}`,'primary','plus'))+summary+`<section class="panel"><div class="studio-list">${sorted.map(r=>`<article class="studio-record"><div><button class="text-link" data-action="studio-edit:${key}/${h(r.id)}"><strong>${h(r.title)}</strong></button>${r.applicationId?`<small>${h(getState().applications.find(a=>a.id===r.applicationId)?.name||'Application removed')}</small>`:''}${d.fields.filter(f=>r[f.key]!==''&&r[f.key]!=null).slice(0,4).map(f=>`<p><span class="muted">${h(f.label)}:</span> ${h(String(r[f.key]).slice(0,240))}</p>`).join('')}${key==='habits'?`<div class="habit-week">${Array.from({length:7},(_,i)=>{const date=shiftDay(today(),i-6),done=(r.doneDates||[]).includes(date);return `<button data-action="studio-habit:${h(r.id)}/${date}" aria-pressed="${done}" aria-label="${h(r.title)} ${date}" class="${done?'done':''}"><small>${dateLabel(date)}</small><strong>${done?'✓':'·'}</strong></button>`;}).join('')}</div><small>${habitStreak(r,today())} day current streak</small>`:''}${key==='collegeScores'?`<strong>Personal fit: ${fitScore(r,weights())?.toFixed(2)||'—'} / 5</strong>`:''}${r.url&&safeUrl(r.url)?`<a href="${h(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}</div><div class="button-group">${ibtn('edit','Edit record',`studio-edit:${key}/${h(r.id)}`)}${btn('Archive',`studio-archive:${key}/${h(r.id)}`,'ghost')}</div></article>`).join('')||'<p class="body-copy">No records yet. Add your first one above.</p>'}</div></section><div class="button-group">${btn('Export CSV',`studio-csv:${key}`,'secondary','download')}${btn('Archived records',`studio-archived:${key}`,'ghost')}</div><a class="text-link" href="#studio">← All studio tools</a>`;}
 function focus(){return header('Focus timer','Choose one thing. Give it a little undivided attention.')+`<section class="panel focus-clock"><span class="eyebrow">${h(timer?.title||'YOUR NEXT FOCUS BLOCK')}</span><output id="focus-countdown" aria-live="off">${clock(remaining())}</output><p id="focus-state">${timer?(remaining()===0?'Session complete. Save it to your focus log.':timer.end?'Focusing · stays accurate if you leave this tab':'Paused'):'25 or 50 minutes, or your own duration.'}</p><div class="button-group">${timer?btn(timer.end?'Pause':'Resume','studio-timer-toggle','secondary')+btn('Save session','studio-timer-save','primary')+btn('Discard','studio-timer-discard','ghost'):btn('Start focus block','studio-timer-start','primary','plus')}</div></section><a class="text-link" href="#focusSessions">View your focus history →</a>`;}
 function review(){const rows=readiness(getState());return header('Submission review','Your own records, gathered into a final review. Always confirm requirements in the official portal.')+`<div class="studio-tool-grid">${rows.map(a=>`<article class="panel"><h2>${h(a.name)}</h2><p>${a.deadline?dateLabel(a.deadline,true):'Deadline not verified'} · ${a.receipts} saved receipts</p><strong>${a.missing.length} required items open</strong><ul>${a.missing.map(r=>`<li>${h(r.title)}</li>`).join('')||'<li>All tracked required items complete.</li>'}</ul><a href="#application/${h(a.id)}" class="text-link">Review application →</a></article>`).join('')||'<p>Add applications to start your review.</p>'}</div><section class="panel"><h2>Also check</h2><p>${list('prompts').filter(r=>r.status!=='Complete').length} unfinished prompts · ${getState().essays.filter(r=>!r.archived&&Number(r.limit)>0&&r.body.trim().split(/\s+/).filter(Boolean).length>Number(r.limit)).length} drafts above their word limit.</p><a href="#receipts">Open submission receipts →</a></section>`;}
 async function handle(key,arg){if(!key.startsWith('studio-'))return false;const [collection,id]=arg.split('/');switch(key){case'studio-add':editor(collection);break;case'studio-edit':editor(collection,id);break;case'studio-archive':mutate(()=>{const r=getState()[collection].find(x=>x.id===id);if(r)r.archived=true;},'Archived');break;case'studio-archived':{dialog(`<div class="dialog-heading"><h2>Archived records</h2>${btn('Close','close-dialog','ghost')}</div><div>${(getState()[collection]||[]).filter(x=>x.archived).map(r=>`<div class="record-row"><strong>${h(r.title)}</strong>${btn('Restore',`studio-restore:${collection}/${h(r.id)}`,'secondary')}</div>`).join('')||'<p>No archived records.</p>'}</div>`);break;}case'studio-restore':if(mutate(()=>{getState()[collection].find(x=>x.id===id).archived=false;},'Restored'))ctx.closeDialog();break;case'studio-habit':mutate(()=>{const r=getState().habits.find(x=>x.id===collection);if(!r)return;const date=id;r.doneDates=(r.doneDates||[]).includes(date)?r.doneDates.filter(x=>x!==date):[...(r.doneDates||[]),date];},'Check-in updated');break;case'studio-csv':{const d=TOOL_DEFINITIONS.find(x=>x.key===collection);if(!d)break;const fields=['title','applicationId',...d.fields.map(f=>f.key),...(collection==='habits'?['doneDates']:[])];download(`ascend-${collection}.csv`,csv([fields,...list(collection).map(r=>fields.map(f=>Array.isArray(r[f])?r[f].join(';'):r[f]??''))]),'text/csv');break;}case'studio-weights':formDialog('Decision weights',Object.keys(weights()).map(k=>field(k,k,weights()[k],'number','min="0" max="100" required step="any"')).join(''),v=>{if(Object.values(v).every(x=>Number(x)===0))throw Error('Give at least one factor a positive weight.');return mutate(()=>getState().profile.decisionWeights=Object.fromEntries(Object.entries(v).map(([k,v])=>[k,Number(v)])),'Weights saved');});break;case'studio-timer-start':formDialog('Start focus block',field('What will you work on?','title','','text','required maxlength="180"')+field('Minutes','minutes',25,'number','required min="1" max="180"'),v=>{const minutes=Number(v.minutes);if(!Number.isInteger(minutes)||minutes<1||minutes>180)throw Error('Choose 1–180 minutes.');timer={title:v.title,minutes,remaining:minutes*60,end:Date.now()+minutes*60000};putTimer();ctx.render();});break;case'studio-timer-toggle':if(timer){timer.end?(timer.remaining=remaining(),timer.end=null):timer.end=Date.now()+timer.remaining*1000;putTimer();ctx.render();}break;case'studio-timer-discard':timer=null;putTimer();ctx.render();break;case'studio-timer-save':if(timer){const done=Math.floor((timer.minutes*60-remaining())/60);if(done<1){toast('Focus for at least a minute before saving.');break;}if(mutate(()=>{getState().focusSessions=getState().focusSessions||[];getState().focusSessions.push({id:uid(),title:timer.title,date:today(),minutes:done,notes:'',created:Date.now()});},'Focus session saved')){timer=null;putTimer();ctx.render();}}break;default:return false;}return true;}
 setInterval(()=>{const el=document.querySelector('#focus-countdown');if(el){el.textContent=clock(remaining());if(timer&&remaining()===0)document.querySelector('#focus-state').textContent='Session complete. Save it to your focus log.';}},1000);
 return {renderPage:base=>base==='studio'?overview():base==='focus'?focus():base==='readiness'?review():toolsPage(base),handle};
}
